  const { t, c } = current;
  const r = landingRow(c);
  grid[r][c] = t;
  t.r = r;
  t.c = c;
  t.el.classList.remove('falling', 'spawn');
  current = null;
  lastCol = c;
  drops++;
  fast = false;
  updateGhost();

  state = 'resolving';
  const id = gameId;
  resolve(t).then(() => {
    if (id !== gameId || state !== 'resolving') return;
    state = 'playing';
    spawn();
  });
}

function sameNeighbors(t) {
  const out = [];
  for (const [dr, dc] of [[1, 0], [0, -1], [0, 1], [-1, 0]]) {
    const r = t.r + dr, c = t.c + dc;
    if (r < 0 || r >= ROWS || c < 0 || c >= COLS) continue;
    const n = grid[r][c];
    if (n && n.value === t.value) out.push(n);
  }
  return out;
}

// 이웃한 같은 숫자를 t로 모두 흡수: 1개면 x2, 2개면 x4, 3개면 x8
async function mergeInto(t, neighbors) {
  for (const n of neighbors) {
    grid[n.r][n.c] = null;
    n.alive = false;
    place(n.el, t.r, t.c);
  }
  await sleep(MOVE_MS);
  neighbors.forEach((n) => n.el.remove());
  t.value *= 2 ** neighbors.length;
  paint(t.el, t.value);
  t.el.classList.remove('pop');
  void t.el.offsetWidth; // 애니메이션 재시작
  t.el.classList.add('pop');
  score += t.value;
  updateScore();
  await sleep(MOVE_MS);
}

// 빈 칸 아래로 블록 떨어뜨리기. 움직인 타일 목록 반환
async function gravity() {
  const moved = [];
  for (let c = 0; c < COLS; c++) {
    let write = ROWS - 1;
    for (let r = ROWS - 1; r >= 0; r--) {
      const t = grid[r][c];
      if (!t) continue;
      if (r !== write) {
        grid[write][c] = t;
        grid[r][c] = null;
        t.r = write;
        place(t.el, write, c);
        moved.push(t);
      }
      write--;
    }
  }
  if (moved.length) await sleep(MOVE_MS + 20);
  return moved;
}

// 연쇄 합치기: 변화가 생긴 타일들을 계속 검사
async function resolve(start) {
  const id = gameId;
  let active = [start];
  while (true) {
    active = active.filter((t) => t.alive).sort((a, b) => b.r - a.r);
    const idx = active.findIndex((t) => sameNeighbors(t).length > 0);
    if (idx < 0) return;
    const t = active[idx];
    await mergeInto(t, sameNeighbors(t));
    if (id !== gameId) return;
    const moved = await gravity();
    if (id !== gameId) return;
    active = [...new Set([t, ...moved, ...active])];
  }
}

function gameOver() {
  state = 'over';
  current = null;
  updateGhost();
  updateScore();
  showOverlay('게임 오버', `점수 ${score}`, '다시 하기', newGame);
}

function newGame() {
  gameId++;
  tilesLayer.innerHTML = '';
  grid = Array.from({ length: ROWS }, () => Array(COLS).fill(null));
  current = null;
  score = 0;
  drops = 0;
  lastCol = Math.floor(COLS / 2);
  fast = soft = false;
  nextValue = genNext();
  updateScore();
  hideOverlay();
  state = 'playing';
  spawn();
}

function togglePause() {
  if (state === 'playing') {
    state = 'paused';
    showOverlay('일시정지', '', '계속하기', togglePause);
  } else if (state === 'paused') {
    state = 'playing';
    hideOverlay();
  }
}

// ---------- 메인 루프 ----------

let lastTs = 0;
function loop(ts) {
  const dt = Math.min((ts - lastTs) / 1000, 0.05);
  lastTs = ts;
  if (state === 'playing' && current) {
    current.y += fallSpeed() * dt;
    const target = landingRow(current.c);
    if (current.y >= target) {
      current.y = target;
      drawCurrent();
      land();
    } else {
      drawCurrent();
    }
  }
  requestAnimationFrame(loop);
}

// ---------- 입력 ----------

function colFromX(x) {
  const rect = bgLayer.getBoundingClientRect();
  return Math.max(0, Math.min(COLS - 1, Math.floor(((x - rect.left) / rect.width) * COLS)));
}

let dragging = false;
board.addEventListener('pointerdown', (e) => {
  if (state !== 'playing' || !current) return;
  dragging = true;
  board.setPointerCapture(e.pointerId);
  moveTo(colFromX(e.clientX));
});
board.addEventListener('pointermove', (e) => {
  if (dragging) moveTo(colFromX(e.clientX));
});
board.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false;
  if (current) fast = true;
});
board.addEventListener('pointercancel', () => { dragging = false; });

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowLeft': move(-1); break;
    case 'ArrowRight': move(1); break;
    case 'ArrowDown': soft = true; break;
    case 'ArrowUp':
    case ' ': if (state === 'playing' && current) fast = true; break;
    case 'p': case 'P': case 'Escape': togglePause(); break;
    default: return;
  }
  e.preventDefault();
});
document.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowDown') soft = false;
});

$('pauseBtn').addEventListener('click', togglePause);
$('restartBtn').addEventListener('click', newGame);
$('ovBtn').onclick = newGame;
window.addEventListener('resize', resize);
document.addEventListener('visibilitychange', () => {
  if (document.hidden && state === 'playing') togglePause();
});

// ---------- 시작 ----------

grid = Array.from({ length: ROWS }, () => Array(COLS).fill(null));
setupBoard();
nextValue = genNext();
renderNext();
updateScore();
requestAnimationFrame((ts) => { lastTs = ts; requestAnimationFrame(loop); });

