// 연쇄 합치기: 변화가 생긴 타일들을 계속 검사
async function resolve(start) {
  const id = gameId;
  let active = [start];
  while (true) {
    active = active.filter((t) => t.alive).sort((a, b) => b.r - a.r);
    const idx = active.findIndex((t) => sameNeighbors(t).length > 0);
    if (idx < 0) return;
    const t = active[idx];
    await mergeInto(t, sameNeighbors(t));
    if (id !== gameId) return;
    const moved = await gravity();
    if (id !== gameId) return;
    active = [...new Set([t, ...moved, ...active])];
  }
}

input.new_string:
// 연쇄 처리: 변화가 생긴 타일들을 계속 검사. 같은 숫자 합치기가 끝자리 0 없애기보다 우선
async function resolve(start) {
  const id = gameId;
  let active = [start];
  while (true) {
    active = active.filter((t) => t.alive).sort((a, b) => b.r - a.r);
    const t = active.find((x) => sameNeighbors(x).length || tenNeighbors(x).length);
    if (!t) return;
    const same = sameNeighbors(t);
    if (same.length) await mergeInto(t, same);
    else await vanishPair(t, tenNeighbors(t)[0]);
    if (id !== gameId) return;
    const moved = await gravity();
    if (id !== gameId) return;
    active = [...new Set([t, ...moved, ...active])];
  }
}

