// 상하좌우 이웃 중 조건에 맞는 타일 (아래쪽 우선)
function neighborsWhere(t, match) {
  const out = [];
  for (const [dr, dc] of [[1, 0], [0, -1], [0, 1], [-1, 0]]) {
    const r = t.r + dr, c = t.c + dc;
    if (r < 0 || r >= ROWS || c < 0 || c >= COLS) continue;
    const n = grid[r][c];
    if (n && match(n)) out.push(n);
  }
  return out;
}

const sameNeighbors = (t) => neighborsWhere(t, (n) => n.value === t.value);
// 두 계열 모두 끝자리가 0이나 5가 될 수 없어서, 같은 숫자끼리는 여기에 걸리지 않음
const tenNeighbors = (t) => neighborsWhere(t, (n) => (n.value + t.value) % 10 === 0);

// 합이 끝자리 0인 두 타일을 함께 없애고 합계만큼 점수
async function vanishPair(t, n) {
  const sum = t.value + n.value;
  for (const x of [t, n]) {
    grid[x.r][x.c] = null;
    x.alive = false;
    x.el.classList.add('vanish');
  }
  showFloat(`+${sum}`, t.r, t.c);
  score += sum;
  updateScore();
  await sleep(MOVE_MS * 2);
  t.el.remove();
  n.el.remove();
}

function showFloat(text, r, c) {
  const el = document.createElement('div');
  el.className = 'float';
  el.textContent = text;
  place(el, r, c);
  tilesLayer.append(el);
  setTimeout(() => el.remove(), 800);
}

// 이웃한 같은 숫자를 t로 모두 흡수: 1개면 x2, 2개면 x4, 3개면 x8
async function mergeInto(t, neighbors) {
  for (const n of neighbors) {
    grid[n.r][n.c] = null;
    n.alive = false;
    place(n.el, t.r, t.c);
  }
