function highestTile() {
  let hi = 2;
  for (const row of grid) for (const t of row) if (t && t.value > hi) hi = t.value;
  return hi;
}

// 다음 숫자: 2 계열/3 계열 중 하나를 반반 확률로 고름.
// 보드의 최고 숫자에 따라 범위가 넓어지고, 작은 숫자가 더 자주 나옴
function genNext() {
  const tiers = Math.max(3, Math.min(6, Math.floor(Math.log2(highestTile() / 16))));
  const base = Math.random() < 0.5 ? 2 : 3;
  const pool = [];
  for (let i = 0; i < tiers; i++) pool.push(base * 2 ** i);
  const weights = pool.map((_, i) => pool.length - i);
  let pick = Math.random() * weights.reduce((a, b) => a + b, 0);
  for (let i = 0; i < pool.length; i++) {
    pick -= weights[i];
    if (pick < 0) return pool[i];
  }
  return pool[0];
}

